WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM web_events), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM with_gaps) SELECT id, event_time, duration_sec, session_id_2 FROM sessionized ORDER BY session_id_2 DESC NULLS LAST
